import type { View } from '@/lib/bindings'

// Generated by gui/tests/scenarios from the shared CLI recordings and app fixtures.
const fixtures = import.meta.glob<View>('../src/scenarios/*.json', {
  eager: true,
  import: 'default',
})
export const scenarios = Object.entries(fixtures).map(([path, view]) => ({
  name:
    path
      .split('/')
      .at(-1)
      ?.replace(/\.json$/, '') ?? '',
  view,
}))

export function scenarioByName(name: string) {
  const scenario = scenarios.find((entry) => entry.name === name)
  if (!scenario) throw new Error(`Missing scenario: ${name}`)
  return scenario
}
